### 6. Database Setup File - C:\Users\felth\Downloads\FlowGuard\server\models\index.js

```javascript
'use strict';

const fs = require('fs');
const path = require('path');
const Sequelize = require('sequelize');
const basename = path.basename(__filename);
const db = {};
require('dotenv').config();

let sequelize = new Sequelize(
  process.env.DB_NAME,
  process.env.DB_USER,
  process.env.DB_PWD,
  {
    host: process.env.DB_HOST,
    port: process.env.DB_PORT,
    dialect: 'postgres',
    logging: false 
  }
);

fs
  .readdirSync(__dirname)
  .filter(file => {
    return (file.indexOf('.') !== 0) && (file !== basename) && (file.slice(-3) === '.js');
  })
  .forEach(file => {
    const model = require(path.join(__dirname, file))(sequelize, Sequelize.DataTypes);
    db[model.name] = model;
  });

Object.keys(db).forEach(modelName => {
  if (db[modelName].associate) {
    db[modelName].associate(db);
  }
});

db.sequelize = sequelize;
db.Sequelize = Sequelize;

module.exports = db;
```

**Key Features:**
- Dynamically loads all `.js` model files from the models directory
- Initializes Sequelize with PostgreSQL (dialect: 'postgres')
- Uses environment variables for database credentials (DB_NAME, DB_USER, DB_PWD, DB_HOST, DB_PORT)
- Calls associate methods on all models for relationships
- Logging disabled (`logging: false`)

---

### 7. Seed File - C:\Users\felth\Downloads\FlowGuard\server\seed.js

```javascript
const { User } = require('./models'); // Adjust path if your models folder is elsewhere
const bcrypt = require('bcrypt');

/**
 * SEED SCRIPT: Creates the initial Facilities Manager (FM)
 * Run this command in your terminal: node seed.js
 */
const seedFirstAdmin = async () => {
    try {
        console.log("--- Starting FlowGuard System Bootstrap ---");

        // 1. Define the Master Admin Credentials
        const adminEmail = 'admin@harrison.com';
        const adminPassword = 'Admin123!'; // Your team can change this after logging in
        const hashedPassword = await bcrypt.hash(adminPassword, 10);

        // 2. Use findOrCreate to prevent duplicates
        const [user, created] = await User.findOrCreate({
            where: { email: adminEmail },
            defaults: {
                name: 'System Root Admin',
                email: adminEmail,
                password: hashedPassword,
                role: 'FM',
                isActive: true,
                companyCode: 'ROOT-ACCESS-001' // Optional internal identifier
            }
        });

        if (created) {
            console.log("\n✅ SUCCESS: Initial FM created.");
            console.log("------------------------------------------");
            console.log(`Email:    ${adminEmail}`);
            console.log(`Password: ${adminPassword}`);
            console.log("------------------------------------------");
            console.log("You can now log in at the /login page.");
        } else {
            console.log("\nℹ️  INFO: Admin account already exists in the database.");
        }

        process.exit(0); // Exit successfully
    } catch (err) {
        console.error("\n❌ ERROR: Failed to seed admin user.");
        console.error(err.message);
        process.exit(1); // Exit with error
    }
};

// Execute the function
seedFirstAdmin();
```

**Key Features:**
- Creates initial Facilities Manager (FM) account
- Default credentials: `admin@harrison.com` / `Admin123!`
- Uses bcrypt for password hashing (10 rounds)
- Uses `findOrCreate` to prevent duplicate admin accounts
- Exits with code 0 on success, 1 on failure
- Run with: `node seed.js`

---

### Additional Model Details

**User Model** - C:\Users\felth\Downloads\FlowGuard\server\models\User.js
- **Paranoid: false** (hard deletes enabled)
- Role types: FM, Tenant, Staff
- Includes biometric enrollment support (isEnrolled, faceVector)
- Supports hybrid registration with companyCode and 48-hour expiration
- Manager-staff hierarchy relationships
- Attendance tracking

**Staff Model** - C:\Users\felth\Downloads\FlowGuard\server\models\Staff.js
- **Paranoid: true** (soft deletes)
- Stores face embeddings (TEXT field)
- Links to staff roles and names

All files are located in the server directory as specified.

