  const checkIsExpired = () => {
    if (!usage.createdAt) return false;
    const fortyEightHours = 48 * 60 * 60 * 1000;
    const timeElapsed = Date.now() - new Date(usage.createdAt).getTime();
    return timeElapsed > fortyEightHours;
