2	import axios from 'axios';
3	import Sidebar from '../components/Sidebar';
4	import '../css/Dashboard.css';
5	import '../css/VPatrol.css'; // Reusing your high-tech tracking box and HUD dashboard styles
6	
7	const GateScanner = () => {
8	  const videoRef = useRef(null);
9	  const canvasRef = useRef(null);
10	  
11	  const [scanStatus, setScanStatus] = useState("SYSTEM_ACTIVE"); 
12	  const [displayMessage, setDisplayMessage] = useState("PLACE FACE IN VIEWPORT");
13	  const [faceBox, setFaceBox] = useState(null); 
14	  const [scanProgress, setScanProgress] = useState(0); 
15	  
16	  const scanStatusRef = useRef("SYSTEM_ACTIVE");
17	  const lockTimerRef = useRef(null);
18	  const progressIntervalRef = useRef(null);
19	  const candidateUserRef = useRef(null); 
20	
21	  const token = localStorage.getItem("accessToken");
22	  const ATTENDANCE_SCAN_URL = "/api/attendance/scan";
23	
24	  const changeScanState = (nextState, message) => {
25	    setScanStatus(nextState);
26	    scanStatusRef.current = nextState;
27	    if (message) setDisplayMessage(message);
28	  };
29	
30	  useEffect(() => {
31	    startGateCamera();
32	    const scanInterval = setInterval(() => performPerimeterScan(), 800); 
33	
34	    return () => {
35	      stopGateCamera();
36	      clearInterval(scanInterval);
37	      if (lockTimerRef.current) clearTimeout(lockTimerRef.current);
38	      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
39	    };
40	  }, []);
41	
42	  const startGateCamera = async () => {
43	    try {
44	      const stream = await navigator.mediaDevices.getUserMedia({ 
45	        video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: "user" } 
46	      });
47	      if (videoRef.current) videoRef.current.srcObject = stream;
48	      changeScanState("SYSTEM_ACTIVE", "GATE TURNSTILE ONLINE // AWAITING TARGET");
49	    } catch (err) { 
50	      changeScanState("HARDWARE_ERR", "HARDWARE FAILURE: CAMERA NOT DETECTED"); 
51	    }
52	  };
53	
54	  const stopGateCamera = () => {
55	    if (videoRef.current?.srcObject) {
56	      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
57	    }
58	  };
59	
60	  const processAttendanceTransaction = async (verifiedName) => {
61	    changeScanState("SECURE_MATCH", "IDENTITY VERIFIED // PROCESSING TIMECARD");
62	    setScanProgress(100);
63	
64	    try {
65	      // 🎯 Hit the Node.js automatic clock-in/out controller
66	      const res = await axios.post(ATTENDANCE_SCAN_URL, { name: verifiedName }, {
67	        headers: { Authorization: `Bearer ${token}` }
68	      });
69	
70	      if (res.data && res.data.action) {
71	        // Render the exact system response action directly onto the kiosk screen
72	        const actionMessage = res.data.action.replace(/_/g, " ");
73	        setDisplayMessage(`🔓 ${verifiedName}: ${actionMessage}`);
74	      }
75	    } catch (err) {
76	      console.error("Attendance Sync Failed:", err);
77	      setDisplayMessage("🚨 GATE TRANSACTION ROUTING FAULT");
78	    }
79	
80	    setTimeout(() => { resetTurnstileKiosk(); }, 4000);
81	  };
82	
83	  const performPerimeterScan = async () => {
84	    const video = videoRef.current;
85	    const canvas = canvasRef.current;
86	    
87	    if (!video || !canvas || video.videoWidth === 0) return;
88	    if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") return;
89	
90	    const context = canvas.getContext('2d');
91	    canvas.width = video.videoWidth;
92	    canvas.height = video.videoHeight;
93	    context.drawImage(video, 0, 0, canvas.width, canvas.height);
94	    const imageBase64 = canvas.toDataURL('image/jpeg', 0.4);
95	
96	    try {
97	      const res = await axios.post('/ai/user/recognize', { image: imageBase64 }, {
98	        headers: { Authorization: `Bearer ${token}` }
99	      });
100	
101	      if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") return;
102	
103	      if (res.data && res.data.box && res.data.box.length >= 4) {
104	        let rawX, rawY, boxWidth, boxHeight;
105	        const [v1, v2, v3, v4] = res.data.box;
106	        if (v2 > v4 && v3 > v1) { rawY = v1; rawX = v4; boxWidth = v2 - v4; boxHeight = v3 - v1; } 
107	        else { rawX = v1; rawY = v2; boxWidth = v3; boxHeight = v4; }
108	        
109	        const faceProximityPercentage = (boxWidth / video.videoWidth) * 100; 
110	        const livenessRatio = res.data.liveness_ratio || 0.5;
111	
112	        const targetBox = {
113	          left: `${(rawX / video.videoWidth) * 100}%`, top: `${(rawY / video.videoHeight) * 100}%`,
114	          width: `${(boxWidth / video.videoWidth) * 100}%`, height: `${(boxHeight / video.videoHeight) * 100}%`
115	        };
116	
117	        if (faceProximityPercentage < 8 && scanStatusRef.current !== "LIVENESS_CHECK") {
118	          changeScanState("PRESENCE_DETECTED", "TARGET DETECTED // MOVE CLOSER");
119	          setFaceBox(null); 
120	          return;
121	        }
122	
123	        // 🎯 LIVENESS CHECK: Wait for head swing rotation
124	        if (scanStatusRef.current === "LIVENESS_CHECK") {
125	          setFaceBox(targetBox);
126	          if (livenessRatio < 0.35 || livenessRatio > 0.65) {
127	            await processAttendanceTransaction(candidateUserRef.current);
128	          }
129	          return;
130	        }
131	
132	        // TARGET LOCKING SEQUENCE
133	        if (scanStatusRef.current === "SYSTEM_ACTIVE" || scanStatusRef.current === "PRESENCE_DETECTED") {
134	          changeScanState("TARGET_LOCKING", "LOCKING BIOMETRIC VECTORS...");
135	          setFaceBox(targetBox);
136	          setScanProgress(12);
137	
138	          let progress = 12;
139	          progressIntervalRef.current = setInterval(() => {
140	            progress += Math.floor(Math.random() * 14) + 4;
141	            if (progress >= 96) { setScanProgress(96); clearInterval(progressIntervalRef.current); } 
142	            else { setScanProgress(progress); }
143	          }, 120);
144	
145	          lockTimerRef.current = setTimeout(() => {
146	            clearInterval(progressIntervalRef.current);
147	
148	            if (res.data.user && res.data.user.name !== "UNAUTHORIZED") {
149	              candidateUserRef.current = res.data.user.name;
